cat /proc/uptime; S=/var/opt/public/sin; ls -la --full-time $S/recmgr $S/crashhandler 2>&1 | cut -c1-160 | head -30; which sqlite3; sqlite3 $S/recmgr/recmgr_stats.db "select * from Crash order by rowid desc limit 8" 2>&1 | cut -c1-300; echo ---; strings $S/recmgr/recmgr_stats.db 2>/dev/null | tail -25 | cut -c1-200; echo ---; cat $S/recmgr/restartInfo.xml $S/crashhandler/restartInfo.xml 2>/dev/null | head -30; find /var/opt /var/volatile /tmp -xdev -mmin -40 \( -iname "*core*" -o -iname "*crash*" \) 2>/dev/null | head -20
